// frontend/src/helpers/api.ts
import axios, { AxiosError, AxiosInstance } from "axios";
import type { CreateUserInput, CreateUserResponse } from "../types/user";

const serverUrl = process.env.REACT_APP_API_URL ?? "http://localhost:3001/api";

class Api {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: serverUrl,
      headers: { "Content-Type": "application/json" },
    });
  }

  async createUser(input: CreateUserInput): Promise<CreateUserResponse> {
    try {
      const { data } = await this.client.post<CreateUserResponse>(
        "/users",
        input,
      );
      return data;
    } catch (error) {
      const message =
        error instanceof AxiosError
          ? (error.response?.data?.message ?? "Request failed")
          : "Request failed";
      throw new Error(message);
    }
  }
}

export default new Api();

// frontend/src/hooks/use-create-user-form.ts
import { ChangeEvent, FormEvent, useState } from "react";
import api from "../helpers/api";
import type { CreateUserInput } from "../types/user";

const initialValues: CreateUserInput = { email: "", password: "" };

export const useCreateUserForm = () => {
  const [values, setValues] = useState<CreateUserInput>(initialValues);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    const { name, value } = event.target;
    setValues((prev) => ({ ...prev, [name]: value }));
    setError("");
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setIsSubmitting(true);
    setError("");

    try {
      const data = await api.createUser(values);
      setMessage(data.message);
      setValues(initialValues);
    } catch (submitError) {
      setError(
        submitError instanceof Error
          ? submitError.message
          : "Something went wrong",
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  return { values, message, error, isSubmitting, handleChange, handleSubmit };
};

