// backend/src/routes/create-user.ts
import { NextFunction, Request, Response, Router } from "express";
import { publishUserCreatedEvent } from "../events/user-events";
import User from "../models/user";
import { validateCreateUserInput } from "../utils/validate-create-user";

const router = Router();

router.post("/", async (req: Request, res: Response, next: NextFunction) => {
  try {
    const validationError = validateCreateUserInput(req.body);
    if (validationError) {
      return res.status(400).json({ message: validationError });
    }

    const user = new User(req.body);
    await user.save();

    await publishUserCreatedEvent({
      userId: String(user._id),
      email: user.email,
      createdAt: user.createdAt?.toISOString(),
    });

    return res.status(201).json({
      message: "User successfully created",
      user: { id: String(user._id), email: user.email },
    });
  } catch (error) {
    return next(error);
  }
});

export default router;

// backend/src/events/user-events.ts
import { createClient } from "redis";
import { EVENT_CHANNELS } from "../constants/event-channels";
import type { UserCreatedEvent } from "../types/user-created-event";

const publisher = createClient({ url: process.env.REDIS_URL });
const subscriber = createClient({ url: process.env.REDIS_URL });

publisher.on("error", (err) => console.error("Redis publisher error:", err));
subscriber.on("error", (err) => console.error("Redis subscriber error:", err));

export const connectEventBus = async (): Promise<void> => {
  await publisher.connect();
  await subscriber.connect();
};

export const publishUserCreatedEvent = async (
  payload: UserCreatedEvent,
): Promise<void> => {
  await publisher.publish(EVENT_CHANNELS.USER_CREATED, JSON.stringify(payload));
};

export const subscribeToUserCreated = async (
  handler: (payload: UserCreatedEvent) => void,
): Promise<void> => {
  await subscriber.subscribe(EVENT_CHANNELS.USER_CREATED, (message) => {
    handler(JSON.parse(message) as UserCreatedEvent);
  });
};

