// hooks/use-feature-data.ts
import { useEffect, useState } from "react";

export const useFeatureData = () => {
  const [data, setData] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      const result = await fetchData();
      if (!cancelled) {
        setData(result);
        setLoading(false);
      }
    };

    void load();
    return () => {
      cancelled = true;
    };
  }, []);

  return { data, loading };
};

